input.command:
cat > eas.json <<'EOF'
{
  "cli": {
    "version": ">= 12.0.0",
    "appVersionSource": "remote"
  },
  "build": {
    "development": {
      "developmentClient": true,
      "distribution": "internal"
    },
    "preview": {
      "distribution": "internal",
      "android": {
        "buildType": "apk"
      }
    },
    "production": {
      "autoIncrement": true,
      "android": {
        "buildType": "app-bundle"
      }
    }
  },
  "submit": {
    "production": {
      "ios": {
        "ascAppId": "REPLACE_WITH_APP_STORE_CONNECT_APP_ID"
      },
      "android": {
        "serviceAccountKeyPath": "./google-service-account.json",
        "track": "internal",
        "releaseStatus": "completed"
      }
    }
  }
}
EOF
python3 - <<'EOF'
import re
s=open('app.json').read()
s=s.replace('      "buildNumber": "1",\n','').replace('      "versionCode": 1,\n','')
open('app.json','w').write(s)
EOF
grep -q google-service-account .gitignore || printf '\n# Play service account key (placeholder path used in eas.json)\ngoogle-service-account.json\n' >> .gitignore
git diff --stat; python3 -c "import json;json.load(open('eas.json'));json.load(open('app.json'))"

